#include "../src/microvm/gui/NativeGuiBroker.h"
#include <Windows.h>
#include <iostream>
#include <stdexcept>
#include <vector>
namespace u=guardian::nativeuser;using av::microvm::native_gui::Broker;
namespace {unsigned checks=0;void Check(bool ok,const char* why){++checks;char trace[2]{};if(GetEnvironmentVariableA("AEGIS_TEST_TRACE",trace,2))std::cerr<<checks<<" "<<why<<'\n';if(!ok)throw std::runtime_error(why);}
struct Client {Broker broker;uint64_t sequence=0;uint32_t pid=10,tid=20;explicit Client(const std::filesystem::path& helper):broker(helper,1,0,true){}
u::Packet Packet(u::Command c){u::Packet p;p.boot=1;p.session=broker.Enumeration().session;p.sequence=sequence+1;p.pid=pid;p.tid=tid;p.command=c;return p;}
u::Reply Call(u::Command c){auto p=Packet(c);Check(broker.Exchange(p),"Native USER32 transport");++sequence;Check(p.reply.restrictions==31,"Restricted helper");return p.reply;}
u::Reply Op(u::Op op,uint64_t id=0){u::Command c;c.op=op;c.window=id;return Call(c);}};
u::Command Create(u::Class kind=u::Class::Custom,uint64_t parent=0,uint32_t id=0){u::Command c;c.op=u::Op::Create;c.kind=kind;c.other=parent;c.id=id;c.style=parent?WS_CHILD|WS_VISIBLE:WS_OVERLAPPEDWINDOW|WS_VISIBLE;c.rect=parent?u::Rect{10,10,170,42}:u::Rect{100,100,500,360};c.text[0]='N';return c;}
HWND Root(uint32_t pid){struct Search{DWORD pid;HWND h=nullptr;}s{pid};EnumWindows([](HWND h,LPARAM p)->BOOL{auto& x=*reinterpret_cast<Search*>(p);DWORD pid=0;GetWindowThreadProcessId(h,&pid);wchar_t cls[100]{};GetClassNameW(h,cls,100);if(pid==x.pid&&!wcscmp(cls,L"Aegis.NativeUser32.14.10B"))x.h=h;return TRUE;},LPARAM(&s));return s.h;}
}
int main(int argc,char** argv){try{Check(argc==2,"Helper path");const auto helper=std::filesystem::absolute(argv[1]);Client a(helper),b(helper);const auto root=a.Call(Create()).value,other=b.Call(Create()).value;Check(root&&other&&root!=other,"Independent namespaces");const auto native=Root(a.broker.ProcessForTesting());Check(native!=nullptr&&uint64_t(native)!=root,"Real HWND remains outside guest");
    Check(a.Op(u::Op::Query,other).status==ERROR_INVALID_HANDLE,"Foreign session refused");a.pid=11;Check(a.Op(u::Op::Query,root).status==ERROR_INVALID_HANDLE,"Foreign guest process refused");a.pid=10;a.tid=21;Check(a.Op(u::Op::Destroy,root).status==ERROR_ACCESS_DENIED,"Foreign guest thread cannot destroy");a.tid=20;
    const auto button=a.Call(Create(u::Class::Button,root,101)).value,edit=a.Call(Create(u::Class::Edit,root,102)).value;Check(button&&edit,"Real controls created");const auto nativeButton=GetDlgItem(native,101),nativeEdit=GetDlgItem(native,102);wchar_t cls[32]{};GetClassNameW(nativeEdit,cls,32);Check(!_wcsicmp(cls,L"EDIT")&&nativeButton,"Actual Win32 EDIT and BUTTON class");
    u::Command c;c.op=u::Op::NativeMessage;c.window=button;c.message=BM_CLICK;Check(!a.Call(c).status,"Native button dispatch");bool click=false;for(unsigned i=0;i<30;++i){const auto e=a.Op(u::Op::Poll).event;if(!e.window)break;c={};c.op=u::Op::Poll;c.flags=1;const auto event=a.Call(c).event;if(event.message==WM_COMMAND&&event.wp==101&&event.lp==button)click=true;}Check(click,"WM_COMMAND has opaque child ID");
    c={};c.op=u::Op::Text;c.window=edit;c.text[0]='x';Check(!a.Call(c).status,"Native text update");wchar_t text[256]{};DWORD_PTR copied=0;Check(SendMessageTimeoutW(nativeEdit,WM_GETTEXT,256,LPARAM(text),SMTO_ABORTIFHUNG,1000,&copied)!=0,"Read actual EDIT with bounded native message");Check(!wcscmp(text,L"x"),"Guest text is in actual host EDIT");
    c={};c.op=u::Op::NativeMessage;c.window=edit;c.message=WM_COPYDATA;c.lp=uint64_t(native);Check(a.Call(c).status==ERROR_NOT_SUPPORTED,"Arbitrary pointer-bearing native message refused");
    // Exercise native keyboard processing without global input injection.
    PostMessageW(nativeEdit,WM_CHAR,'y',1);Sleep(25);const auto typed=a.Op(u::Op::GetText,edit);Check(wcschr(reinterpret_cast<const wchar_t*>(typed.text),L'y')!=nullptr,"Native EDIT receives real Windows message input");
    c={};c.op=u::Op::Position;c.window=root;c.rect={110,120,550,400};c.flags=SWP_NOACTIVATE|SWP_NOZORDER;Check(!a.Call(c).status,"SetWindowPos native");bool position=false;for(unsigned i=0;i<50;++i){c={};c.op=u::Op::Poll;c.flags=1;auto r=a.Call(c);if(!r.value)break;if(r.event.message==WM_WINDOWPOSCHANGED){Check(r.event.flags&4,"WINDOWPOS has typed payload");Check(!r.event.lp&&r.event.rect.right-r.event.rect.left==440,"No native WINDOWPOS address");position=true;}}Check(position,"Geometry notification present");
    // The separate transport can rendezvous with a window inside a native modal move loop.
    PostMessageW(native,WM_SYSCOMMAND,SC_MOVE,0);Sleep(25);Check(!a.Op(u::Op::Query,root).status,"Helper services IPC inside native modal loop");PostMessageW(native,WM_CANCELMODE,0,0);PostMessageW(native,WM_KEYDOWN,VK_ESCAPE,0);
    c={};c.op=u::Op::Timer;c.window=root;c.wp=7;c.lp=10;Check(a.Call(c).value==7,"Native timer");Sleep(30);bool timer=false;for(unsigned i=0;i<60;++i){c={};c.op=u::Op::Poll;c.flags=1;auto r=a.Call(c);if(!r.value)break;if(r.event.message==WM_TIMER&&r.event.wp==7)timer=true;}Check(timer,"Timer mapped back to guest ID");c={};c.op=u::Op::KillTimer;c.window=root;c.wp=7;Check(!a.Call(c).status,"Timer cleanup");
    a.tid=21;c={};c.op=u::Op::Send;c.window=root;c.message=WM_APP+1;c.wp=3;const auto cookie=a.Call(c).value;Check(cookie,"Interthread send queued");a.tid=20;u::Event sent;for(unsigned i=0;i<60;++i){c={};c.op=u::Op::Poll;c.flags=3;auto r=a.Call(c);if(!r.value)break;if(r.event.cookie){sent=r.event;break;}}Check(sent.cookie==cookie&&(sent.flags&1),"Sent callback event routed to owner");c={};c.op=u::Op::Reply;c.window=cookie;c.wp=200;Check(!a.Call(c).status,"Guest synchronous reply");a.tid=21;Check(a.Op(u::Op::Result,cookie).value==200,"Sender obtains guest return");c={};c.op=u::Op::Send;c.window=root;c.message=WM_APP+1;const auto late=a.Call(c).value;Sleep(2050);Check(a.Op(u::Op::Result,late).status==ERROR_TIMEOUT,"Unresponsive guest callback bounded");a.tid=20;c={};c.op=u::Op::Reply;c.window=late;Check(a.Call(c).status==ERROR_INVALID_HANDLE,"Late reply rejected");
    auto malformed=a.Packet({});malformed.session=b.broker.Enumeration().session;Check(!a.broker.Exchange(malformed),"Wrong session envelope rejected without native action");
    c={};c.op=u::Op::Query;c.window=root;c.text[0]='x';Check(a.Call(c).status==ERROR_INVALID_PARAMETER,"Unused fields rejected");
    std::vector<uint64_t> children;for(unsigned i=3;i<u::MaxWindows;++i){const auto r=a.Call(Create(u::Class::Static,root,i));Check(!r.status,"Window quota available");children.push_back(r.value);}Check(a.Call(Create(u::Class::Static,root,99)).status==ERROR_NOT_ENOUGH_QUOTA,"Window quota enforced");const auto destroyed=a.Op(u::Op::Destroy,root);Check(!destroyed.status&&!destroyed.live[0]&&!destroyed.live[1]&&!destroyed.live[2],"Recursive destruction drains windows, timers and events");Check(a.Op(u::Op::Query,edit).status==ERROR_INVALID_HANDLE&&!IsWindow(nativeEdit),"Child IDs and native HWNDs invalidated");const auto fresh=a.Call(Create()).value;Check(fresh!=root,"Window IDs never reused");a.Op(u::Op::Destroy,fresh);Check(a.Op(u::Op::Finish).completed,"Clean completion");const auto pid=a.broker.ProcessForTesting();a.broker.Finish();Check(a.broker.Completed()&&!Root(pid),"Orderly helper exit leaves no HWND");b.Op(u::Op::Destroy,other);b.Op(u::Op::Finish);b.broker.Finish();
    Client death(helper);death.Call(Create());const auto deadPid=death.broker.ProcessForTesting();death.broker.KillForTesting();auto q=death.Packet({});Check(!death.broker.Exchange(q),"Helper death fails session");death.broker.Finish();Check(!Root(deadPid),"Helper death removes windows");Client stalled(helper);stalled.broker.StallForTesting();q=stalled.Packet({});const auto start=GetTickCount64();Check(!stalled.broker.Exchange(q)&&GetTickCount64()-start<5000,"Hung helper transport bounded and terminated");stalled.broker.Finish();std::cout<<checks<<" native USER32 isolation, native controls, message order, modal IPC, timeout and cleanup checks PASS\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
